"""Local radius-redistribution optimizer for the n=26 unit-square packing.

Given the current centers and radii (passed in by the executor after reading the
program's output), this tool performs a fast, deterministic local redistribution
of the radii subject to the two constraint families:

  * wall:    r_i <= w_i = min(x, y, 1-x, 1-y)
  * neighbor: r_i + r_j <= dist(i, j)

It starts from the supplied radii, then iteratively:
  1. clamps each r_i to its wall cap w_i,
  2. for every overlapping pair (r_i + r_j > d_ij), scales the two down to fit,
  3. for every pair with slack (r_i + r_j < d_ij) and a circle below its wall
     cap, grows the smaller-slack circle to use the gap,
until stable. It returns the redistributed radii, the new sum, the sum of the
input radii, and the gain. This is a LOCAL optimum around the given centers —
it tells the executor exactly how much radius is recoverable by pure
redistribution (no center moves) and which circles to shrink/grow.

No program execution, no file I/O, no introspection. Pure math on the args.
"""
import math


def _clamp(v, lo, hi):
    if v < lo:
        return lo
    if v > hi:
        return hi
    return v


def run(ctx, args):
    centers = args.get("centers")
    radii = args.get("radii")
    if not centers or not radii:
        return {"error": "need 'centers' (list of [x,y]) and 'radii' (list of floats)"}
    n = len(centers)
    if len(radii) != n:
        return {"error": "centers and radii length mismatch"}

    xs = [float(c[0]) for c in centers]
    ys = [float(c[1]) for c in centers]
    r = [float(v) for v in radii]

    wall = [min(xs[i], ys[i], 1.0 - xs[i], 1.0 - ys[i]) for i in range(n)]
    wall = [_clamp(w, 0.0, 1.0) for w in wall]

    # pairwise distances
    d = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            d[i][j] = d[j][i] = math.hypot(xs[i] - xs[j], ys[i] - ys[j])

    in_sum = sum(r)
    # start: clamp to wall
    for i in range(n):
        r[i] = _clamp(r[i], 0.0, wall[i])

    for _ in range(60):
        changed = 0.0
        # resolve overlaps
        for i in range(n):
            for j in range(i + 1, n):
                s = r[i] + r[j]
                if s > d[i][j] and s > 0.0:
                    scale = d[i][j] / s
                    r[i] *= scale
                    r[j] *= scale
                    changed += s - d[i][j]
        # grow into slack: for each pair with gap, push the smaller circle up
        for i in range(n):
            for j in range(i + 1, n):
                gap = d[i][j] - (r[i] + r[j])
                if gap <= 1e-12:
                    continue
                # grow the circle with more wall headroom, up to min(gap, headroom)
                hi = wall[i] - r[i]
                hj = wall[j] - r[j]
                if hi <= 1e-12 and hj <= 1e-12:
                    continue
                if hi >= hj:
                    grow = min(gap, hi)
                    if grow > 0.0:
                        r[i] += grow
                        changed += grow
                else:
                    grow = min(gap, hj)
                    if grow > 0.0:
                        r[j] += grow
                        changed += grow
        # final wall clamp
        for i in range(n):
            if r[i] > wall[i]:
                r[i] = wall[i]
        if changed < 1e-9:
            break

    out_sum = sum(r)
    # verify no overlap remains
    worst = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            ov = r[i] + r[j] - d[i][j]
            if ov > worst:
                worst = ov

    # circles that could still grow (wall headroom)
    headroom = [round(wall[i] - r[i], 6) for i in range(n)]
    top = sorted(range(n), key=lambda i: headroom[i], reverse=True)[:5]

    return {
        "n": n,
        "input_sum": round(in_sum, 6),
        "output_sum": round(out_sum, 6),
        "gain": round(out_sum - in_sum, 6),
        "max_overlap_after": round(worst, 9),
        "radii": [round(v, 6) for v in r],
        "top_wall_headroom": [
            {"i": int(i), "headroom": headroom[i], "wall": round(wall[i], 6)}
            for i in top
        ],
    }

